export const getGetTenantSummaryQueryKey = (tenantId: string) => {
  return [`/api/tenants/${tenantId}/summary`] as const;
};

export const getGetTenantSummaryQueryOptions = <
  TData = Awaited<ReturnType<typeof getTenantSummary>>,
  TError = ErrorType<unknown>,
>(
  tenantId: string,
  options?: {
    query?: UseQueryOptions<
      Awaited<ReturnType<typeof getTenantSummary>>,
      TError,
      TData
    >;
    request?: SecondParameter<typeof customFetch>;
  },
) => {
  const { query: queryOptions, request: requestOptions } = options ?? {};

  const queryKey =
    queryOptions?.queryKey ?? getGetTenantSummaryQueryKey(tenantId);

  const queryFn: QueryFunction<
    Awaited<ReturnType<typeof getTenantSummary>>
  > = ({ signal }) => getTenantSummary(tenantId, { signal, ...requestOptions });

  return {
    queryKey,
    queryFn,
    enabled: !!tenantId,
    ...queryOptions,
  } as UseQueryOptions<
    Awaited<ReturnType<typeof getTenantSummary>>,
    TError,
    TData
  > & { queryKey: QueryKey };
};

export type GetTenantSummaryQueryResult = NonNullable<
  Awaited<ReturnType<typeof getTenantSummary>>
>;
export type GetTenantSummaryQueryError = ErrorType<unknown>;

/**
 * @summary Get tenant dashboard summary counts
 */

export function useGetTenantSummary<
  TData = Awaited<ReturnType<typeof getTenantSummary>>,
  TError = ErrorType<unknown>,
>(
  tenantId: string,
  options?: {
    query?: UseQueryOptions<
      Awaited<ReturnType<typeof getTenantSummary>>,
      TError,
      TData
    >;
    request?: SecondParameter<typeof customFetch>;
  },
): UseQueryResult<TData, TError> & { queryKey: QueryKey } {
  const queryOptions = getGetTenantSummaryQueryOptions(tenantId, options);

  const query = useQuery(queryOptions) as UseQueryResult<TData, TError> & {
    queryKey: QueryKey;
  };

  return { ...query, queryKey: queryOptions.queryKey };
}
